#!/bin/bash
# All GTA comparators + Jev arms in one session per lane (t1 split, Qwen2.5-7B); LG/TG/JB from the caller
: "${LG:?}" "${TG:?}" "${JB:?}"; M=/datasets/omni_pretraining/gta2/models/Qwen2.5-7B-Instruct; X=/datasets/omni_pretraining/gta2/scripts_extra
API=0 MODEL=$M TYPES=read_arith,count_arith SPLIT=t1 FRESH=jva ARMS=notools,full,random,router,bm25,dense,tool2vec,tto,beam,jevA,jevB,jevC GTA_EXTRA_MENUS="jevA=/datasets/omni_pretraining/gta2/results/jev/menus_A_{type}.json,jevB=/datasets/omni_pretraining/gta2/results/jev/menus_B_{type}.json,jevC=/datasets/omni_pretraining/gta2/results/jev/menus_C_{type}.json" TAG=jva_7b MENU_TAG=7b GTA_OBS_ROLE=user LGPU=$LG TGPU=$TG LPORT=8963 TPORT=16813 PPORT=16913 JOB=$JB bash $X/gta_jev_lane.sh
API=1 GTA_SRCH=1 MODEL=$M TYPES=web_fact SPLIT=t1 FRESH=jvaw ARMS=notools,full,random,router,bm25,dense,tool2vec,tto,beam,jevA,jevB,jevC GTA_EXTRA_MENUS="jevA=/datasets/omni_pretraining/gta2/results/jev/menus_A_{type}.json,jevB=/datasets/omni_pretraining/gta2/results/jev/menus_B_{type}.json,jevC=/datasets/omni_pretraining/gta2/results/jev/menus_C_{type}.json" GTA_TRAJ_SFX=_api TAG=jvaw_7b MENU_TAG=7b GTA_OBS_ROLE=user LGPU=$LG TGPU=$TG LPORT=8964 TPORT=16814 PPORT=16914 JOB=$JB bash $X/gta_jev_lane.sh
